  "steps": [
    {
      "text": "Очистите картофель и нарежьте его крупными кусками.",
      "timer_seconds": null
    },
    {
      "text": "Налейте воду в кастрюлю, положите картофель и поставьте на огонь.",
      "timer_seconds": null
    },
    {
      "text": "Отварите картофель до готовности около 20 минут после закипания.",
      "timer_seconds": 1200
    },
    {
      "text": "Пока варится картофель, нарежьте куриное филе небольшими кусками.",
      "timer_seconds": null
    },
    {
      "text": "Мелко нарежьте лук и натрите морковь на тёрке.",
      "timer_seconds": null
    },
    {
      "text": "Разогрейте масло на сковороде и обжарьте курицу до золотистой корочки около 10 минут.",
      "timer_seconds": 600
    },
    {
      "text": "Добавьте к курице лук и морковь, жарьте вместе ещё 5 минут.",
      "timer_seconds": 300
    },
    {
      "text": "Слейте воду с картофеля, разомните его в пюре.",
      "timer_seconds": null
    },
    {
      "text": "Добавьте соль в пюре и хорошо перемешайте.",
      "timer_seconds": null
    },
    {
      "text": "Положите пюре на тарелку, сверху выложите обжаренную курицу с овощами.",
      "timer_seconds": null
    }
  ]
}
